import React, { useState, useEffect } from 'react';
import {
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  TablePagination,
  Paper,
  Button,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  TextField,
  Select,
  MenuItem,
  FormControl,
  InputLabel,
  Grid,
  IconButton,
  Typography,
  Card,
  CardContent,
  Box,
  Chip,
  InputAdornment,
  Collapse,
  CircularProgress,
  Divider,
  Alert,
  Snackbar,
  useTheme,
  useMediaQuery,
  Avatar
} from '@mui/material';
import {
  Add as AddIcon,
  Edit as EditIcon,
  Delete as DeleteIcon,
  Search as SearchIcon,
  FileDownload as FileDownloadIcon,
  FilterList as FilterListIcon,
  Close as CloseIcon,
  Refresh as RefreshIcon,
  MonetizationOn as MonetizationOnIcon,
  AccountBalance as AccountBalanceIcon,
  CheckCircle as CheckCircleIcon,
  Pending as PendingIcon,
  CancelOutlined as CancelIcon
} from '@mui/icons-material';

const Transactions = () => {
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('sm'));
  const isMediumScreen = useMediaQuery(theme.breakpoints.down('md'));

  // State
  const [transactions, setTransactions] = useState([]);
  const [loading, setLoading] = useState(false);
  const [openDialog, setOpenDialog] = useState(false);
  const [confirmDeleteOpen, setConfirmDeleteOpen] = useState(false);
  const [currentTransaction, setCurrentTransaction] = useState(null);
  const [transactionToDelete, setTransactionToDelete] = useState(null);
  const [formData, setFormData] = useState({
    customer: '',
    amount: '',
    type: 'Thu',
    date: new Date().toISOString().split('T')[0],
    status: 'Đang xử lý',
    paymentMethod: 'Tiền mặt',
    description: ''
  });
  const [searchText, setSearchText] = useState('');
  const [filterVisible, setFilterVisible] = useState(false);
  const [dateFilter, setDateFilter] = useState({
    startDate: '',
    endDate: ''
  });
  const [statusFilter, setStatusFilter] = useState('all');
  const [page, setPage] = useState(0);
  const [rowsPerPage, setRowsPerPage] = useState(10);
  const [snackbar, setSnackbar] = useState({
    open: false,
    message: '',
    severity: 'success'
  });

  // Statistics
  const [statistics, setStatistics] = useState({
    totalTransactions: 0,
    totalAmount: 0,
    pendingAmount: 0,
    completedAmount: 0,
  });

  // Fetch transactions from API
  const fetchTransactions = async () => {
    setLoading(true);
    try {
      const token = localStorage.getItem('token');
      console.log('Token đang dùng:', token ? 'Có token' : 'Không có token');

      // Build URL có query params
      const queryParams = new URLSearchParams();
      if (searchText) queryParams.append('searchText', searchText);
      if (statusFilter && statusFilter !== 'all') queryParams.append('statusFilter', statusFilter);
      if (dateFilter.startDate && dateFilter.endDate) {
        queryParams.append('startDate', dateFilter.startDate);
        queryParams.append('endDate', dateFilter.endDate);
      }

      const apiUrl = `http://localhost:5000/api/transactions?${queryParams.toString()}`;
      console.log('Đang gọi API:', apiUrl);

      const response = await fetch(apiUrl, {
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        }
      });

      console.log('Response status:', response.status, response.statusText);

      if (!response.ok) {
        const errorText = await response.text();
        console.error('Error response:', errorText);
        throw new Error(`API trả về lỗi ${response.status}: ${response.statusText}`);
      }

      const data = await response.json();
      console.log('Dữ liệu nhận được:', data);

      setTransactions(data);

      // Cập nhật thống kê
      if (Array.isArray(data)) {
        const totalTransactions = data.length;
        let totalAmount = 0;
        let pendingAmount = 0;
        let completedAmount = 0;

        data.forEach(transaction => {
          const amount = parseFloat(transaction.amount) || 0;
          totalAmount += amount;

          if (transaction.status === 'Đang xử lý') {
            pendingAmount += amount;
          } else if (transaction.status === 'Đã hoàn thành') {
            completedAmount += amount;
          }
        });

        setStatistics({
          totalTransactions,
          totalAmount,
          pendingAmount,
          completedAmount
        });
      }
    } catch (error) {
      console.error('Lỗi fetch transactions:', error);
      showSnackbar('Không thể tải dữ liệu giao dịch: ' + error.message, 'error');
    } finally {
      setLoading(false);
    }
  };

  // Thêm useEffect này ngay sau khai báo hàm fetchTransactions
  useEffect(() => {
    console.log('Component Transactions đã mount, đang tải dữ liệu...');
    fetchTransactions();
  }, []); // Mảng dependencies rỗng sẽ chỉ chạy useEffect này một lần khi component mount

  // Định dạng tiền tệ
  const formatCurrency = (amount) => {
    return new Intl.NumberFormat('vi-VN', {
      style: 'currency',
      currency: 'VND'
    }).format(amount);
  };

  // Xử lý thay đổi dữ liệu biểu mẫu
  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData({
      ...formData,
      [name]: value
    });
  };

  // Xử lý thay đổi bộ lọc ngày
  const handleDateFilterChange = (e) => {
    const { name, value } = e.target;
    setDateFilter({
      ...dateFilter,
      [name]: value
    });
  };

  // Hiển thị thông báo snackbar
  const showSnackbar = (message, severity = 'success') => {
    setSnackbar({
      open: true,
      message,
      severity
    });
  };

  // Xử lý đóng snackbar
  const handleCloseSnackbar = () => {
    setSnackbar({
      ...snackbar,
      open: false
    });
  };

  // Xử lý chỉnh sửa giao dịch
  const handleEdit = (transaction) => {
    console.log('Dữ liệu giao dịch cần sửa:', transaction);

    setCurrentTransaction(transaction);

    // Map dữ liệu từ API sang form
    setFormData({
      customer: transaction.customer,
      amount: transaction.amount,
      // Chuyển đổi từ 'thu'/'chi' (backend) sang 'Thu'/'Chi' (frontend)
      type: transaction.transactionType === 'thu' ? 'Thu' : 'Chi',
      date: transaction.date,
      status: transaction.status,
      paymentMethod: transaction.paymentMethod,
      description: transaction.description || ''
    });

    setOpenDialog(true);
  };

  // Xử lý thêm giao dịch mới
  const handleAdd = () => {
    setCurrentTransaction(null);
    setFormData({
      customer: '',
      amount: '',
      type: 'Thu',
      date: new Date().toISOString().split('T')[0],
      status: 'Đang xử lý',
      paymentMethod: 'Tiền mặt',
      description: ''
    });
    setOpenDialog(true);
  };

  // Xử lý xóa giao dịch
  const handleDeleteClick = (transaction) => {
    setTransactionToDelete(transaction);
    setConfirmDeleteOpen(true);
  };

  const handleConfirmDelete = async () => {
    if (transactionToDelete) {
      setLoading(true);
      try {
        const token = localStorage.getItem('token');
        console.log('Đang xóa giao dịch:', transactionToDelete._id);

        const response = await fetch(`http://localhost:5000/api/transactions/delete/${transactionToDelete._id}`, {
          method: 'DELETE',
          headers: {
            'Authorization': `Bearer ${token}`
          }
        });

        console.log('Response status xóa:', response.status);

        if (!response.ok) {
          const errorText = await response.text();
          console.error('Lỗi khi xóa:', errorText);
          throw new Error(`Không thể xóa giao dịch: ${response.status}`);
        }

        const data = await response.json();
        console.log('Kết quả xóa:', data);

        showSnackbar('Xóa giao dịch thành công');
        fetchTransactions(); // Tải lại dữ liệu sau khi xóa
      } catch (error) {
        console.error('Lỗi khi xóa giao dịch:', error);
        showSnackbar('Không thể xóa giao dịch: ' + error.message, 'error');
      } finally {
        setLoading(false);
        setConfirmDeleteOpen(false);
        setTransactionToDelete(null);
      }
    }
  };


  // Xử lý lưu giao dịch
  const handleSave = async () => {
    if (!formData.customer || !formData.amount || !formData.date) {
      showSnackbar('Vui lòng điền đầy đủ thông tin bắt buộc', 'error');
      return;
    }

    setLoading(true);
    try {
      const token = localStorage.getItem('token');

      // Map các giá trị để khớp với schema backend
      const formattedData = {
        customer: formData.customer,
        amount: parseFloat(formData.amount),
        transactionType: formData.type === 'Thu' ? 'thu' : 'chi', // Chuyển 'Thu'/'Chi' sang 'thu'/'chi'
        description: formData.description || "",
        transactionDate: formData.date,
        paymentMethod: formData.paymentMethod,
        status: formData.status
      };

      console.log('Dữ liệu gửi lên:', formattedData);

      if (currentTransaction) {
        const response = await fetch(`http://localhost:5000/api/transactions/update/${currentTransaction._id}`, {
          method: 'PUT',
          headers: {
            'Content-Type': 'application/json',
            'Authorization': `Bearer ${token}`
          },
          body: JSON.stringify(formattedData),
        });

        if (!response.ok) {
          const errorText = await response.text();
          console.error('Lỗi response:', errorText);
          throw new Error(`Cập nhật thất bại: ${response.status}`);
        }

        const data = await response.json();
        showSnackbar('Cập nhật giao dịch thành công');
        fetchTransactions();

      } else {
        const response = await fetch('http://localhost:5000/api/transactions/add', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'Authorization': `Bearer ${token}`
          },
          body: JSON.stringify(formattedData),
        });

        if (!response.ok) {
          const errorText = await response.text();
          console.error('Lỗi response:', errorText);
          throw new Error(`Thêm thất bại: ${response.status}`);
        }

        const data = await response.json();
        showSnackbar('Thêm giao dịch thành công');
        fetchTransactions();
      }

      setOpenDialog(false);
    } catch (error) {
      console.error('Lỗi khi lưu giao dịch:', error);
      showSnackbar('Không thể lưu giao dịch: ' + error.message, 'error');
    } finally {
      setLoading(false);
    }
  };

  // Xử lý xuất dữ liệu
  const handleExport = async () => {
    setLoading(true);
    try {
      // Đây sẽ là nơi gọi API xuất dữ liệu thực tế
      // const response = await fetch('/api/transactions/export', {
      //   method: 'POST',
      //   headers: {
      //     'Content-Type': 'application/json',
      //   },
      //   body: JSON.stringify({ 
      //     searchText, 
      //     dateFilter, 
      //     statusFilter 
      //   }),
      // });
      // const blob = await response.blob();
      // const url = window.URL.createObjectURL(blob);
      // const a = document.createElement('a');
      // a.href = url;
      // a.download = 'transactions.xlsx';
      // document.body.appendChild(a);
      // a.click();
      // a.remove();

      // Giả lập độ trễ API
      await new Promise(resolve => setTimeout(resolve, 1000));

      showSnackbar('Xuất dữ liệu thành công');
    } catch (error) {
      console.error('Lỗi khi xuất dữ liệu:', error);
      showSnackbar('Không thể xuất dữ liệu', 'error');
    } finally {
      setLoading(false);
    }
  };

  // Xử lý thay đổi trang
  const handleChangePage = (event, newPage) => {
    setPage(newPage);
  };

  // Xử lý thay đổi số hàng mỗi trang
  const handleChangeRowsPerPage = (event) => {
    setRowsPerPage(parseInt(event.target.value, 10));
    setPage(0);
  };

  // Màu sắc trạng thái
  const getStatusColor = (status) => {
    switch (status) {
      case 'Đã hoàn thành':
        return 'success';
      case 'Đang xử lý':
        return 'primary';
      case 'Hủy':
        return 'error';
      default:
        return 'default';
    }
  };

  // Lấy biểu tượng trạng thái
  const getStatusIcon = (status) => {
    switch (status) {
      case 'Đã hoàn thành':
        return <CheckCircleIcon fontSize="small" />;
      case 'Đang xử lý':
        return <PendingIcon fontSize="small" />;
      case 'Hủy':
        return <CancelIcon fontSize="small" />;
      default:
        return null;
    }
  };

  // Lấy màu loại giao dịch
  const getTypeColor = (type) => {
    return type === 'Thu' ? '#4caf50' : '#f44336';
  };

  return (
    <Box sx={{
      padding: { xs: '16px', md: '24px' },
      backgroundColor: '#f5f5f5',
      minHeight: '100vh'
    }}>
      <Paper
        elevation={0}
        sx={{
          p: { xs: 2, md: 3 },
          mb: 3,
          borderRadius: '12px',
          backgroundImage: 'linear-gradient(120deg, #84fab0 0%, #8fd3f4 100%)',
          color: 'white'
        }}
      >
        <Typography
          variant="h4"
          gutterBottom
          sx={{
            fontWeight: 'bold',
            textShadow: '1px 1px 2px rgba(0,0,0,0.1)'
          }}
        >
          Quản lý giao dịch
        </Typography>
        <Typography variant="body1">
          Quản lý tất cả các giao dịch thu chi của doanh nghiệp
        </Typography>
      </Paper>

      {/* Thẻ thống kê */}
      <Grid container spacing={3} sx={{ mb: 4 }}>
        <Grid item xs={12} sm={6} md={3}>
          <Card
            elevation={0}
            sx={{
              borderRadius: '12px',
              height: '100%',
              transition: 'transform 0.3s',
              '&:hover': {
                transform: 'translateY(-5px)',
                boxShadow: '0 8px 16px rgba(0,0,0,0.1)'
              }
            }}
          >
            <CardContent sx={{ p: 3 }}>
              <Box display="flex" alignItems="center" mb={2}>
                <Avatar
                  sx={{
                    bgcolor: '#bbdefb',
                    color: '#1976d2',
                    width: 48,
                    height: 48,
                    mr: 2
                  }}
                >
                  <AccountBalanceIcon />
                </Avatar>
                <Typography color="textSecondary" variant="subtitle2">
                  Tổng số giao dịch
                </Typography>
              </Box>
              <Typography variant="h4" sx={{ fontWeight: 'bold' }}>
                {statistics.totalTransactions}
              </Typography>
              <Typography variant="caption" color="textSecondary">
                Tất cả giao dịch trong hệ thống
              </Typography>
            </CardContent>
          </Card>
        </Grid>
        <Grid item xs={12} sm={6} md={3}>
          <Card
            elevation={0}
            sx={{
              borderRadius: '12px',
              height: '100%',
              transition: 'transform 0.3s',
              '&:hover': {
                transform: 'translateY(-5px)',
                boxShadow: '0 8px 16px rgba(0,0,0,0.1)'
              }
            }}
          >
            <CardContent sx={{ p: 3 }}>
              <Box display="flex" alignItems="center" mb={2}>
                <Avatar
                  sx={{
                    bgcolor: '#c8e6c9',
                    color: '#388e3c',
                    width: 48,
                    height: 48,
                    mr: 2
                  }}
                >
                  <MonetizationOnIcon />
                </Avatar>
                <Typography color="textSecondary" variant="subtitle2">
                  Tổng giá trị
                </Typography>
              </Box>
              <Typography variant="h4" sx={{ fontWeight: 'bold' }}>
                {formatCurrency(statistics.totalAmount)}
              </Typography>
              <Typography variant="caption" color="textSecondary">
                Tổng giá trị giao dịch
              </Typography>
            </CardContent>
          </Card>
        </Grid>
        <Grid item xs={12} sm={6} md={3}>
          <Card
            elevation={0}
            sx={{
              borderRadius: '12px',
              height: '100%',
              transition: 'transform 0.3s',
              '&:hover': {
                transform: 'translateY(-5px)',
                boxShadow: '0 8px 16px rgba(0,0,0,0.1)'
              }
            }}
          >
            <CardContent sx={{ p: 3 }}>
              <Box display="flex" alignItems="center" mb={2}>
                <Avatar
                  sx={{
                    bgcolor: '#fff9c4',
                    color: '#fbc02d',
                    width: 48,
                    height: 48,
                    mr: 2
                  }}
                >
                  <PendingIcon />
                </Avatar>
                <Typography color="textSecondary" variant="subtitle2">
                  Đang xử lý
                </Typography>
              </Box>
              <Typography variant="h4" sx={{ fontWeight: 'bold' }}>
                {formatCurrency(statistics.pendingAmount)}
              </Typography>
              <Typography variant="caption" color="textSecondary">
                Tổng giá trị giao dịch đang xử lý
              </Typography>
            </CardContent>
          </Card>
        </Grid>
        <Grid item xs={12} sm={6} md={3}>
          <Card
            elevation={0}
            sx={{
              borderRadius: '12px',
              height: '100%',
              transition: 'transform 0.3s',
              '&:hover': {
                transform: 'translateY(-5px)',
                boxShadow: '0 8px 16px rgba(0,0,0,0.1)'
              }
            }}
          >
            <CardContent sx={{ p: 3 }}>
              <Box display="flex" alignItems="center" mb={2}>
                <Avatar
                  sx={{
                    bgcolor: '#c8e6c9',
                    color: '#388e3c',
                    width: 48,
                    height: 48,
                    mr: 2
                  }}
                >
                  <CheckCircleIcon />
                </Avatar>
                <Typography color="textSecondary" variant="subtitle2">
                  Đã hoàn thành
                </Typography>
              </Box>
              <Typography variant="h4" sx={{ fontWeight: 'bold' }}>
                {formatCurrency(statistics.completedAmount)}
              </Typography>
              <Typography variant="caption" color="textSecondary">
                Tổng giá trị giao dịch đã hoàn thành
              </Typography>
            </CardContent>
          </Card>
        </Grid>
      </Grid>

      {/* Thanh công cụ */}
      <Paper
        elevation={0}
        sx={{
          p: { xs: 2, md: 3 },
          mb: 3,
          borderRadius: '12px',
          display: 'flex',
          flexWrap: 'wrap',
          gap: 2,
          alignItems: 'center'
        }}
      >
        <TextField
          label="Tìm kiếm"
          variant="outlined"
          size="small"
          value={searchText}
          onChange={(e) => setSearchText(e.target.value)}
          InputProps={{
            startAdornment: (
              <InputAdornment position="start">
                <SearchIcon />
              </InputAdornment>
            ),
          }}
          sx={{
            minWidth: { xs: '100%', sm: 300 },
            '& .MuiOutlinedInput-root': {
              borderRadius: '8px'
            }
          }}
          placeholder="Tìm theo tên khách hàng hoặc mô tả"
        />

        <Box sx={{ ml: 'auto', display: 'flex', gap: 1, flexWrap: 'wrap' }}>
          <Button
            variant="outlined"
            startIcon={<FilterListIcon />}
            onClick={() => setFilterVisible(!filterVisible)}
            sx={{
              borderRadius: '8px',
              boxShadow: 'none'
            }}
          >
            Bộ lọc
          </Button>

          <Button
            variant="contained"
            startIcon={<AddIcon />}
            onClick={handleAdd}
            sx={{
              borderRadius: '8px',
              bgcolor: '#4caf50',
              '&:hover': {
                bgcolor: '#388e3c'
              },
              boxShadow: 'none'
            }}
          >
            Thêm giao dịch
          </Button>

          <Button
            variant="outlined"
            startIcon={<FileDownloadIcon />}
            onClick={handleExport}
            sx={{
              borderRadius: '8px',
              boxShadow: 'none'
            }}
          >
            Xuất Excel
          </Button>

          <IconButton
            color="primary"
            onClick={fetchTransactions}
            sx={{
              borderRadius: '8px',
              border: '1px solid rgba(25, 118, 210, 0.5)'
            }}
          >
            <RefreshIcon />
          </IconButton>
        </Box>
      </Paper>

      {/* Bộ lọc */}
      <Collapse in={filterVisible}>
        <Paper
          elevation={0}
          sx={{
            p: { xs: 2, md: 3 },
            mb: 3,
            borderRadius: '12px',
            border: '1px solid #e0e0e0'
          }}
        >
          <Grid container spacing={3} alignItems="center">
            <Grid item xs={12} md={6}>
              <Grid container spacing={2}>
                <Grid item xs={12} sm={6}>
                  <TextField
                    label="Từ ngày"
                    type="date"
                    name="startDate"
                    value={dateFilter.startDate}
                    onChange={handleDateFilterChange}
                    InputLabelProps={{ shrink: true }}
                    fullWidth
                    size="small"
                    sx={{
                      '& .MuiOutlinedInput-root': {
                        borderRadius: '8px'
                      }
                    }}
                  />
                </Grid>
                <Grid item xs={12} sm={6}>
                  <TextField
                    label="Đến ngày"
                    type="date"
                    name="endDate"
                    value={dateFilter.endDate}
                    onChange={handleDateFilterChange}
                    InputLabelProps={{ shrink: true }}
                    fullWidth
                    size="small"
                    sx={{
                      '& .MuiOutlinedInput-root': {
                        borderRadius: '8px'
                      }
                    }}
                  />
                </Grid>
              </Grid>
            </Grid>
            <Grid item xs={12} md={3}>
              <FormControl
                fullWidth
                size="small"
                sx={{
                  '& .MuiOutlinedInput-root': {
                    borderRadius: '8px'
                  }
                }}
              >
                <InputLabel>Trạng thái</InputLabel>
                <Select
                  value={statusFilter}
                  label="Trạng thái"
                  onChange={(e) => setStatusFilter(e.target.value)}
                >
                  <MenuItem value="all">Tất cả trạng thái</MenuItem>
                  <MenuItem value="Đã hoàn thành">Đã hoàn thành</MenuItem>
                  <MenuItem value="Đang xử lý">Đang xử lý</MenuItem>
                  <MenuItem value="Hủy">Hủy</MenuItem>
                </Select>
              </FormControl>
            </Grid>
            <Grid item xs={12} md={3}>
              <Button
                variant="outlined"
                onClick={() => {
                  setDateFilter({
                    startDate: '',
                    endDate: ''
                  });
                  setStatusFilter('all');
                }}
                sx={{
                  borderRadius: '8px',
                  boxShadow: 'none'
                }}
                fullWidth={isMobile}
                startIcon={<CloseIcon />}
              >
                Xóa bộ lọc
              </Button>
            </Grid>
          </Grid>
        </Paper>
      </Collapse>

      {/* Bảng giao dịch */}
      <Paper
        elevation={0}
        sx={{
          borderRadius: '12px',
          overflow: 'hidden',
          border: '1px solid #e0e0e0'
        }}
      >
        <Box p={2} display="flex" justifyContent="space-between" alignItems="center">
          <Typography variant="h6" sx={{ fontWeight: 'bold' }}>
            Danh sách giao dịch
          </Typography>
          {loading && (
            <Box display="flex" alignItems="center" gap={1}>
              <CircularProgress size={20} />
              <Typography variant="body2" color="textSecondary">
                Đang tải...
              </Typography>
            </Box>
          )}
        </Box>
        <Divider />
        <TableContainer>
          <Table>
            <TableHead sx={{ bgcolor: '#f5f5f5' }}>
              <TableRow>
                <TableCell sx={{ fontWeight: 'bold' }}>ID</TableCell>
                <TableCell sx={{ fontWeight: 'bold' }}>Khách hàng</TableCell>
                <TableCell sx={{ fontWeight: 'bold' }}>Số tiền</TableCell>
                <TableCell sx={{ fontWeight: 'bold' }}>Loại</TableCell>
                <TableCell sx={{ fontWeight: 'bold' }}>Trạng thái</TableCell>
                <TableCell sx={{ fontWeight: 'bold' }}>Ngày</TableCell>
                <TableCell sx={{ fontWeight: 'bold' }}>Phương thức</TableCell>
                <TableCell align="right" sx={{ fontWeight: 'bold' }}>Thao tác</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {loading ? (
                <TableRow>
                  <TableCell colSpan={8} align="center" sx={{ py: 5 }}>
                    <CircularProgress size={40} sx={{ mb: 2 }} />
                    <Typography variant="body1" display="block">
                      Đang tải dữ liệu...
                    </Typography>
                  </TableCell>
                </TableRow>
              ) : transactions.length > 0 ? (
                transactions.slice(page * rowsPerPage, page * rowsPerPage + rowsPerPage).map((transaction) => (
                  <TableRow
                    key={transaction._id}
                    sx={{
                      '&:hover': {
                        bgcolor: 'rgba(0, 0, 0, 0.04)'
                      },
                      transition: 'background-color 0.2s'
                    }}
                  >
                    <TableCell>{transaction._id}</TableCell>
                    <TableCell>{transaction.customer}</TableCell>
                    <TableCell sx={{ fontWeight: 'medium' }}>
                      {formatCurrency(transaction.amount)}
                    </TableCell>
                    <TableCell>
                      <Chip
                        label={transaction.transactionType === 'thu' ? 'Thu' : transaction.transactionType === 'chi' ? 'Chi' : transaction.type}
                        size="small"
                        sx={{
                          bgcolor: transaction.transactionType === 'thu' || transaction.type === 'Thu' ? '#4caf50' : '#f44336',
                          color: 'white',
                          fontWeight: 'bold'
                        }}
                      />
                    </TableCell>
                    <TableCell>
                      <Chip
                        icon={getStatusIcon(transaction.status)}
                        label={transaction.status}
                        color={getStatusColor(transaction.status)}
                        size="small"
                        variant="outlined"
                      />
                    </TableCell>
                    <TableCell>
                      {transaction.transactionDate
                        ? (() => {
                          const date = new Date(transaction.transactionDate);
                          return `${date.getDate().toString().padStart(2, '0')}/${(date.getMonth() + 1).toString().padStart(2, '0')}/${date.getFullYear()}`;
                        })()
                        : transaction.date
                          ? (() => {
                            const date = new Date(transaction.date);
                            return `${date.getDate().toString().padStart(2, '0')}/${(date.getMonth() + 1).toString().padStart(2, '0')}/${date.getFullYear()}`;
                          })()
                          : 'Không có ngày'}
                    </TableCell>
                    <TableCell>{transaction.paymentMethod}</TableCell>
                    <TableCell align="right">
                      <IconButton
                        size="small"
                        onClick={() => handleEdit(transaction)}
                        color="primary"
                        sx={{
                          mr: 1,
                          bgcolor: 'rgba(25, 118, 210, 0.1)',
                          '&:hover': {
                            bgcolor: 'rgba(25, 118, 210, 0.2)'
                          }
                        }}
                      >
                        <EditIcon fontSize="small" />
                      </IconButton>
                      <IconButton
                        size="small"
                        onClick={() => handleDeleteClick(transaction)}
                        color="error"
                        sx={{
                          bgcolor: 'rgba(211, 47, 47, 0.1)',
                          '&:hover': {
                            bgcolor: 'rgba(211, 47, 47, 0.2)'
                          }
                        }}
                      >
                        <DeleteIcon fontSize="small" />
                      </IconButton>
                    </TableCell>
                  </TableRow>
                ))
              ) : (
                <TableRow>
                  <TableCell colSpan={8} align="center" sx={{ py: 10 }}>
                    <Box sx={{ textAlign: 'center' }}>
                      <AccountBalanceIcon sx={{ fontSize: 60, color: '#9e9e9e', mb: 2 }} />
                      <Typography variant="h6" gutterBottom color="textSecondary">
                        Chưa có dữ liệu giao dịch
                      </Typography>
                      <Typography variant="body2" color="textSecondary" mb={3}>
                        Bạn có thể thêm giao dịch mới bằng cách nhấn vào nút "Thêm giao dịch"
                      </Typography>
                      <Button
                        variant="contained"
                        startIcon={<AddIcon />}
                        onClick={handleAdd}
                        sx={{
                          borderRadius: '8px',
                          boxShadow: 'none',
                        }}
                      >
                        Thêm giao dịch
                      </Button>
                    </Box>
                  </TableCell>
                </TableRow>
              )}
            </TableBody>
          </Table>
        </TableContainer>
        <Divider />
        <TablePagination
          rowsPerPageOptions={[5, 10, 25, 50]}
          component="div"
          count={transactions.length}
          rowsPerPage={rowsPerPage}
          page={transactions.length > 0 ? page : 0}
          onPageChange={handleChangePage}
          onRowsPerPageChange={handleChangeRowsPerPage}
          labelRowsPerPage="Dòng trên trang:"
          labelDisplayedRows={({ from, to, count }) => `${from}-${to} của ${count}`}
          sx={{ borderTop: '1px solid #e0e0e0' }}
        />
      </Paper>

      {/* Hộp thoại Thêm/Sửa */}
      <Dialog
        open={openDialog}
        onClose={() => setOpenDialog(false)}
        maxWidth="md"
        fullWidth
        PaperProps={{
          elevation: 0,
          sx: {
            borderRadius: '12px',
            overflow: 'hidden'
          }
        }}
      >
        <DialogTitle sx={{
          px: 3,
          py: 2,
          bgcolor: '#f5f5f5',
          borderBottom: '1px solid #e0e0e0'
        }}>
          <Typography variant="h6" fontWeight="bold">
            {currentTransaction ? 'Sửa giao dịch' : 'Thêm giao dịch mới'}
          </Typography>
        </DialogTitle>
        <DialogContent dividers sx={{ p: 3 }}>
          <Grid container spacing={3}>
            <Grid item xs={12} md={6}>
              <TextField
                label="Khách hàng"
                name="customer"
                value={formData.customer}
                onChange={handleInputChange}
                fullWidth
                required
                margin="normal"
                placeholder="Nhập tên khách hàng"
                sx={{
                  '& .MuiOutlinedInput-root': {
                    borderRadius: '8px'
                  }
                }}
              />
            </Grid>
            <Grid item xs={12} md={6}>
              <TextField
                label="Số tiền"
                name="amount"
                type="number"
                value={formData.amount}
                onChange={handleInputChange}
                fullWidth
                required
                margin="normal"
                placeholder="Nhập số tiền giao dịch"
                InputProps={{
                  endAdornment: <InputAdornment position="end">VND</InputAdornment>,
                }}
                sx={{
                  '& .MuiOutlinedInput-root': {
                    borderRadius: '8px'
                  }
                }}
              />
            </Grid>
            <Grid item xs={12} md={6}>
              <FormControl
                fullWidth
                margin="normal"
                sx={{
                  '& .MuiOutlinedInput-root': {
                    borderRadius: '8px'
                  }
                }}
              >
                <InputLabel>Loại giao dịch</InputLabel>
                <Select
                  name="type"
                  value={formData.type}
                  onChange={handleInputChange}
                  label="Loại giao dịch"
                >
                  <MenuItem value="Thu">Thu</MenuItem>
                  <MenuItem value="Chi">Chi</MenuItem>
                </Select>
              </FormControl>
            </Grid>
            <Grid item xs={12} md={6}>
              <TextField
                label="Ngày giao dịch"
                name="date"
                type="date"
                value={formData.date}
                onChange={handleInputChange}
                fullWidth
                required
                margin="normal"
                InputLabelProps={{ shrink: true }}
                sx={{
                  '& .MuiOutlinedInput-root': {
                    borderRadius: '8px'
                  }
                }}
              />
            </Grid>
            <Grid item xs={12} md={6}>
              <FormControl
                fullWidth
                margin="normal"
                sx={{
                  '& .MuiOutlinedInput-root': {
                    borderRadius: '8px'
                  }
                }}
              >
                <InputLabel>Trạng thái</InputLabel>
                <Select
                  name="status"
                  value={formData.status}
                  onChange={handleInputChange}
                  label="Trạng thái"
                >
                  <MenuItem value="Đã hoàn thành">Đã hoàn thành</MenuItem>
                  <MenuItem value="Đang xử lý">Đang xử lý</MenuItem>
                  <MenuItem value="Hủy">Hủy</MenuItem>
                </Select>
              </FormControl>
            </Grid>
            <Grid item xs={12} md={6}>
              <FormControl
                fullWidth
                margin="normal"
                sx={{
                  '& .MuiOutlinedInput-root': {
                    borderRadius: '8px'
                  }
                }}
              >
                <InputLabel>Phương thức thanh toán</InputLabel>
                <Select
                  name="paymentMethod"
                  value={formData.paymentMethod}
                  onChange={handleInputChange}
                  label="Phương thức thanh toán"
                >
                  <MenuItem value="Tiền mặt">Tiền mặt</MenuItem>
                  <MenuItem value="Chuyển khoản">Chuyển khoản</MenuItem>
                  <MenuItem value="Thẻ tín dụng">Thẻ tín dụng</MenuItem>
                </Select>
              </FormControl>
            </Grid>
            <Grid item xs={12}>
              <TextField
                label="Mô tả"
                name="description"
                value={formData.description}
                onChange={handleInputChange}
                fullWidth
                multiline
                rows={4}
                margin="normal"
                placeholder="Nhập mô tả chi tiết về giao dịch này"
                sx={{
                  '& .MuiOutlinedInput-root': {
                    borderRadius: '8px'
                  }
                }}
              />
            </Grid>
          </Grid>
        </DialogContent>
        <DialogActions sx={{ p: 2, bgcolor: '#f5f5f5', borderTop: '1px solid #e0e0e0' }}>
          <Button
            onClick={() => setOpenDialog(false)}
            variant="outlined"
            sx={{
              borderRadius: '8px',
              boxShadow: 'none'
            }}
          >
            Hủy
          </Button>
          <Button
            variant="contained"
            onClick={handleSave}
            disabled={loading}
            sx={{
              borderRadius: '8px',
              boxShadow: 'none',
              bgcolor: '#4caf50',
              '&:hover': {
                bgcolor: '#388e3c'
              }
            }}
          >
            {loading ? (
              <>
                <CircularProgress size={20} sx={{ mr: 1, color: 'white' }} />
                Đang xử lý...
              </>
            ) : (
              currentTransaction ? 'Cập nhật' : 'Thêm'
            )}
          </Button>
        </DialogActions>
      </Dialog>

      {/* Hộp thoại Xác nhận xóa */}
      <Dialog
        open={confirmDeleteOpen}
        onClose={() => setConfirmDeleteOpen(false)}
        PaperProps={{
          elevation: 0,
          sx: {
            borderRadius: '12px',
            overflow: 'hidden'
          }
        }}
      >
        <DialogTitle sx={{
          px: 3,
          py: 2,
          bgcolor: '#f5f5f5',
          borderBottom: '1px solid #e0e0e0',
          display: 'flex',
          alignItems: 'center',
          gap: 1
        }}>
          <DeleteIcon color="error" />
          <Typography variant="h6" fontWeight="bold">
            Xác nhận xóa
          </Typography>
        </DialogTitle>
        <DialogContent sx={{ p: 3, mt: 2 }}>
          <Alert severity="warning" sx={{ mb: 2 }}>
            Hành động này không thể hoàn tác sau khi thực hiện.
          </Alert>
          <Typography>
            Bạn có chắc chắn muốn xóa giao dịch {transactionToDelete?.id ? `#${transactionToDelete._id}` : 'này'} không?
          </Typography>
          {transactionToDelete && (
            <Box sx={{ mt: 2, p: 2, bgcolor: '#f5f5f5', borderRadius: '8px' }}>
              <Grid container spacing={2}>
                <Grid item xs={6}>
                  <Typography variant="body2" color="textSecondary">Khách hàng:</Typography>
                  <Typography variant="body1">{transactionToDelete.customer}</Typography>
                </Grid>
                <Grid item xs={6}>
                  <Typography variant="body2" color="textSecondary">Số tiền:</Typography>
                  <Typography variant="body1">{formatCurrency(transactionToDelete.amount)}</Typography>
                </Grid>
                <Grid item xs={6}>
                  <Typography variant="body2" color="textSecondary">Loại:</Typography>
                  <Typography variant="body1">{transactionToDelete.type}</Typography>
                </Grid>
                <Grid item xs={6}>
                  <Typography variant="body2" color="textSecondary">Ngày:</Typography>
                  <Typography variant="body1">{transactionToDelete.date}</Typography>
                </Grid>
              </Grid>
            </Box>
          )}
        </DialogContent>
        <DialogActions sx={{ p: 2, bgcolor: '#f5f5f5', borderTop: '1px solid #e0e0e0' }}>
          <Button
            onClick={() => setConfirmDeleteOpen(false)}
            variant="outlined"
            sx={{
              borderRadius: '8px',
              boxShadow: 'none'
            }}
          >
            Hủy
          </Button>
          <Button
            variant="contained"
            color="error"
            onClick={handleConfirmDelete}
            disabled={loading}
            sx={{
              borderRadius: '8px',
              boxShadow: 'none'
            }}
          >
            {loading ? (
              <>
                <CircularProgress size={20} sx={{ mr: 1, color: 'white' }} />
                Đang xử lý...
              </>
            ) : (
              'Xóa'
            )}
          </Button>
        </DialogActions>
      </Dialog>

      {/* Snackbar thông báo */}
      <Snackbar
        open={snackbar.open}
        autoHideDuration={4000}
        onClose={handleCloseSnackbar}
        anchorOrigin={{ vertical: 'bottom', horizontal: 'right' }}
      >
        <Alert
          onClose={handleCloseSnackbar}
          severity={snackbar.severity}
          variant="filled"
          sx={{
            width: '100%',
            borderRadius: '8px',
            boxShadow: '0 4px 12px rgba(0,0,0,0.15)'
          }}
        >
          {snackbar.message}
        </Alert>
      </Snackbar>
    </Box>
  );
};

export default Transactions;