import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';  // ✅ Import ở đây!
import {
  Box,
  List,
  ListItem,
  ListItemIcon,
  ListItemText,
  Collapse,
  Divider,
  Avatar,
  Typography,
  styled
} from '@mui/material';
import {
  ExpandLess,
  ExpandMore,
  Dashboard,
  People,
  Description,
  Assessment,
  AttachMoney,
  Report,
  Settings,
  Logout
} from '@mui/icons-material';
import logo from '../assets/logo.png';

// import { Link } from 'react-router-dom'; // Removed unused import

// Styled components
const SidebarContainer = styled(Box)(({ theme }) => ({
  width: 260,
  backgroundColor: '#1a2035',
  backgroundImage: 'linear-gradient(to bottom, #1a2035, #232c4b)',
  color: '#fff',
  minHeight: '100vh',
  boxShadow: '4px 0 10px rgba(0, 0, 0, 0.1)',
  display: 'flex',
  flexDirection: 'column',
  position: 'relative',
  transition: 'all 0.3s ease'
}));

const StyledListItem = styled(ListItem)(({ theme, active }) => ({
  margin: '4px 12px',
  borderRadius: '8px',
  backgroundColor: active ? 'rgba(255, 255, 255, 0.1)' : 'transparent',
  '&:hover': {
    backgroundColor: 'rgba(255, 255, 255, 0.1)',
    '& .MuiListItemIcon-root': {
      color: '#5e72e4'
    },
    '& .MuiListItemText-primary': {
      color: '#fff'
    }
  },
  transition: 'all 0.2s ease'
}));

const SidebarHeader = styled(Box)(({ theme }) => ({
  padding: '24px 16px',
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
  borderBottom: '1px solid rgba(255, 255, 255, 0.1)'
}));

const ProfileSection = styled(Box)(({ theme }) => ({
  padding: '12px 16px',
  display: 'flex',
  alignItems: 'center',
  marginTop: 'auto',
  borderTop: '1px solid rgba(255, 255, 255, 0.1)',
  cursor: 'pointer'
}));

const Sidebar = ({ onPageChange }) => {
  const [open, setOpen] = useState(false);
  const [activePage, setActivePage] = useState('dashboard');
  const navigate = useNavigate(); // ✅ Gọi ĐÚNG BÊN TRONG Sidebar!!!

  const handleClick = () => {
    setOpen(!open);
  };

  const handlePageChange = (page) => {
    setActivePage(page);
    navigate(`/${page}`);
    if (onPageChange) {
      onPageChange(page);
    }
  };


  return (
    <SidebarContainer>
      {/* Logo */}
      <SidebarHeader>
        <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
          <img src={logo} alt="Logo" style={{ width: '40px', height: '40px' }} />
          <Typography variant="h6" fontWeight="bold" sx={{ letterSpacing: '1px' }}>
            CRM System
          </Typography>
        </Box>
      </SidebarHeader>

      {/* Navigation Menu */}
      <Box sx={{ mt: 2, flex: 1, overflowY: 'auto' }}>
        <List component="nav" sx={{ padding: '8px 0' }}>
          <StyledListItem
            button
            active={activePage === 'dashboard' ? 1 : 0}
            onClick={() => handlePageChange('dashboard')}
          >
            <ListItemIcon sx={{
              color: activePage === 'dashboard' ? '#5e72e4' : 'rgba(255, 255, 255, 0.7)',
              minWidth: '40px'
            }}>
              <Dashboard />
            </ListItemIcon>
            <ListItemText
              primary="Dashboard"
              sx={{
                '& .MuiListItemText-primary': {
                  fontSize: '0.9rem',
                  fontWeight: activePage === 'dashboard' ? '600' : '400',
                  color: activePage === 'dashboard' ? '#fff' : 'rgba(255, 255, 255, 0.7)'
                }
              }}
            />
          </StyledListItem>

          <StyledListItem
            button
            active={activePage === 'customers' ? 1 : 0}
            onClick={() => handlePageChange('customers')}
          >
            <ListItemIcon sx={{
              color: activePage === 'customers' ? '#5e72e4' : 'rgba(255, 255, 255, 0.7)',
              minWidth: '40px'
            }}>
              <People />
            </ListItemIcon>
            <ListItemText
              primary="Customers"
              sx={{
                '& .MuiListItemText-primary': {
                  fontSize: '0.9rem',
                  fontWeight: activePage === 'customers' ? '600' : '400',
                  color: activePage === 'customers' ? '#fff' : 'rgba(255, 255, 255, 0.7)'
                }
              }}
            />
          </StyledListItem>

          <StyledListItem
            button
            active={activePage === 'transactions' ? 1 : 0}
            onClick={() => handlePageChange('transactions')}
          >
            <ListItemIcon sx={{
              color: activePage === 'transactions' ? '#5e72e4' : 'rgba(255, 255, 255, 0.7)',
              minWidth: '40px'
            }}>
              <Description />
            </ListItemIcon>
            <ListItemText
              primary="Transactions"
              sx={{
                '& .MuiListItemText-primary': {
                  fontSize: '0.9rem',
                  fontWeight: activePage === 'transactions' ? '600' : '400',
                  color: activePage === 'transactions' ? '#fff' : 'rgba(255, 255, 255, 0.7)'
                }
              }}
            />
          </StyledListItem>

          <Box sx={{ my: 1, mx: 3 }}>
            <Divider sx={{ backgroundColor: 'rgba(255, 255, 255, 0.1)' }} />
          </Box>

          <Typography
            variant="caption"
            sx={{
              px: 3,
              py: 1,
              display: 'block',
              color: 'rgba(255, 255, 255, 0.5)',
              fontSize: '0.7rem',
              letterSpacing: '1px',
              textTransform: 'uppercase'
            }}
          >
            Analytics
          </Typography>

          <StyledListItem
            button
            active={activePage === 'analytics' ? 1 : 0}
            onClick={() => handlePageChange('analytics')}
          >
            <ListItemIcon sx={{
              color: activePage === 'analytics' ? '#5e72e4' : 'rgba(255, 255, 255, 0.7)',
              minWidth: '40px'
            }}>
              <Assessment />
            </ListItemIcon>
            <ListItemText
              primary="Analytics"
              sx={{
                '& .MuiListItemText-primary': {
                  fontSize: '0.9rem',
                  fontWeight: activePage === 'analytics' ? '600' : '400',
                  color: activePage === 'analytics' ? '#fff' : 'rgba(255, 255, 255, 0.7)'
                }
              }}
            />
          </StyledListItem>

          <StyledListItem
            button
            active={activePage === 'sales' ? 1 : 0}
            onClick={() => handlePageChange('sales')}
          >
            <ListItemIcon sx={{
              color: activePage === 'sales' ? '#5e72e4' : 'rgba(255, 255, 255, 0.7)',
              minWidth: '40px'
            }}>
              <AttachMoney />
            </ListItemIcon>
            <ListItemText
              primary="Sales"
              sx={{
                '& .MuiListItemText-primary': {
                  fontSize: '0.9rem',
                  fontWeight: activePage === 'sales' ? '600' : '400',
                  color: activePage === 'sales' ? '#fff' : 'rgba(255, 255, 255, 0.7)'
                }
              }}
            />
          </StyledListItem>

          <StyledListItem
            button
            active={activePage === 'reports' ? 1 : 0}
            onClick={() => handlePageChange('reports')}
          >
            <ListItemIcon sx={{
              color: activePage === 'reports' ? '#5e72e4' : 'rgba(255, 255, 255, 0.7)',
              minWidth: '40px'
            }}>
              <Report />
            </ListItemIcon>
            <ListItemText
              primary="Reports"
              sx={{
                '& .MuiListItemText-primary': {
                  fontSize: '0.9rem',
                  fontWeight: activePage === 'reports' ? '600' : '400',
                  color: activePage === 'reports' ? '#fff' : 'rgba(255, 255, 255, 0.7)'
                }
              }}
            />
          </StyledListItem>
        </List>
      </Box>

      {/* User Profile Section */}
      <ProfileSection onClick={handleClick}>
        <Avatar
          src="/avatar.jpg"
          alt="John Smith"
          sx={{
            width: 38,
            height: 38,
            bgcolor: '#5e72e4',
            border: '2px solid rgba(255, 255, 255, 0.2)',
            boxShadow: '0 4px 8px rgba(0,0,0,0.1)'
          }}
        >
          JS
        </Avatar>
        <Box sx={{ ml: 2, flex: 1 }}>
          <Typography variant="subtitle2" sx={{ fontWeight: 'bold' }}>
            John Smith
          </Typography>
          <Typography variant="caption" sx={{ color: 'rgba(255, 255, 255, 0.6)' }}>
            Administrator
          </Typography>
        </Box>
        {open ? <ExpandLess /> : <ExpandMore />}
      </ProfileSection>

      <Collapse in={open} timeout="auto" unmountOnExit>
        <List component="div" sx={{ backgroundColor: 'rgba(0, 0, 0, 0.2)' }}>
          <StyledListItem button>
            <ListItemIcon sx={{ color: 'rgba(255, 255, 255, 0.7)', minWidth: '40px' }}>
              <Settings fontSize="small" />
            </ListItemIcon>
            <ListItemText
              primary="Settings"
              sx={{
                '& .MuiListItemText-primary': {
                  fontSize: '0.9rem',
                  color: 'rgba(255, 255, 255, 0.7)'
                }
              }}
            />
          </StyledListItem>
          <StyledListItem
            button
            onClick={() => {
              localStorage.removeItem('token');
              window.location.href = '/login';
            }}
          >
            <ListItemIcon sx={{ color: 'rgba(255, 255, 255, 0.7)', minWidth: '40px' }}>
              <Logout fontSize="small" />
            </ListItemIcon>
            <ListItemText
              primary="Log Out"
              sx={{
                '& .MuiListItemText-primary': {
                  fontSize: '0.9rem',
                  color: 'rgba(255, 255, 255, 0.7)'
                }
              }}
            />
          </StyledListItem>

        </List>
      </Collapse>
    </SidebarContainer>
  );
};

export default Sidebar;