import React, { useState, useEffect } from 'react';
import { Box, Grid, Card, CardContent, Typography, IconButton, Avatar, Divider, Paper, Button, Menu, MenuItem } from '@mui/material';
import { 
  Search, Notifications, ArrowUpward, ArrowDownward, People, 
  MonetizationOn, TrendingUp, Assessment, MoreVert, 
  CalendarToday, FilterList, Download, Refresh
} from '@mui/icons-material';
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Legend } from 'recharts';
import { BarChart, Bar } from 'recharts';

const Dashboard = () => {
  // State để điều khiển các menu và bộ lọc
  const [anchorEl, setAnchorEl] = useState(null);
  const [timeFilter, setTimeFilter] = useState('Tháng này');
  
  // Hàm xử lý menu
  const handleMenuOpen = (event) => {
    setAnchorEl(event.currentTarget);
  };
  
  const handleMenuClose = () => {
    setAnchorEl(null);
  };
  
  const handleTimeFilterChange = (filter) => {
    setTimeFilter(filter);
    handleMenuClose();
  };

  // Tooltip tùy chỉnh cho biểu đồ
  const CustomTooltip = ({ active, payload, label }) => {
    if (active && payload && payload.length) {
      return (
        <Paper elevation={3} sx={{ p: 2, bgcolor: 'rgba(255, 255, 255, 0.9)' }}>
          <Typography variant="subtitle2" sx={{ mb: 1 }}>{label}</Typography>
          <Box sx={{ display: 'flex', flexDirection: 'column', gap: 0.5 }}>
            {payload.map((entry, index) => (
              <Box key={`item-${index}`} sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                <Box sx={{ width: 12, height: 12, bgcolor: entry.color, borderRadius: '50%' }} />
                <Typography variant="body2">{`${entry.name}: ${entry.value ? entry.value.toLocaleString('vi-VN') : 0} ₫`}</Typography>
              </Box>
            ))}
          </Box>
        </Paper>
      );
    }
    return null;
  };

  return (
    <Box sx={{ padding: '24px', backgroundColor: '#f8fafc', minHeight: '100vh' }}>
      {/* Phần Header */}
      <Box sx={{ 
        display: 'flex', 
        justifyContent: 'space-between', 
        alignItems: 'center', 
        marginBottom: '24px',
        borderBottom: '1px solid #e0e0e0',
        paddingBottom: '16px'
      }}>
        <Box>
          <Typography variant="h4" fontWeight="bold" color="#1e293b">Bảng Điều Khiển</Typography>
          <Typography variant="subtitle1" color="text.secondary">Chào mừng trở lại! Đây là tổng quan hệ thống của bạn</Typography>
        </Box>
        <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
          <Paper elevation={0} sx={{ 
            display: 'flex', 
            alignItems: 'center', 
            paddingLeft: '12px', 
            paddingRight: '12px', 
            borderRadius: '20px',
            backgroundColor: '#f1f5f9',
            height: '40px',
            transition: 'all 0.3s ease',
            '&:hover': {
              backgroundColor: '#e2e8f0',
              boxShadow: '0 2px 8px rgba(0,0,0,0.05)'
            }
          }}>
            <Search sx={{ color: '#64748b', mr: 1 }} />
            <input 
              style={{ 
                border: 'none', 
                backgroundColor: 'transparent', 
                outline: 'none',
                width: '150px',
                fontSize: '14px'
              }} 
              placeholder="Tìm kiếm..." 
            />
          </Paper>
          <IconButton sx={{ 
            backgroundColor: '#f1f5f9', 
            position: 'relative',
            transition: 'all 0.3s ease',
            '&:hover': {
              backgroundColor: '#e2e8f0'
            }
          }}>
            <Notifications sx={{ color: '#64748b' }} />
            <Box sx={{ 
              position: 'absolute', 
              top: '5px', 
              right: '5px', 
              width: '10px', 
              height: '10px', 
              borderRadius: '50%', 
              backgroundColor: '#ef4444',
              border: '2px solid white'
            }} />
          </IconButton>
          <Divider orientation="vertical" flexItem sx={{ height: '30px' }} />
          <Box sx={{ 
            display: 'flex', 
            alignItems: 'center', 
            gap: 1, 
            padding: '4px 8px',
            borderRadius: '12px',
            cursor: 'pointer',
            transition: 'all 0.3s ease',
            '&:hover': {
              backgroundColor: '#f1f5f9'
            }
          }}>
            <Avatar sx={{ 
              width: 36, 
              height: 36, 
              bgcolor: '#0ea5e9',
              boxShadow: '0 2px 6px rgba(0,0,0,0.1)'
            }}>NV</Avatar>
            <Box>
              <Typography variant="body2" fontWeight="bold">Nguyễn Văn A</Typography>
              <Typography variant="caption" color="text.secondary">Quản trị viên</Typography>
            </Box>
          </Box>
        </Box>
      </Box>

      {/* Các chỉ số tổng quan */}
      <Grid container spacing={3} sx={{ marginBottom: '24px' }}>
        {/* Tổng khách hàng */}
        <Grid item xs={12} sm={6} md={3}>
          <Card sx={{ 
            borderRadius: '16px', 
            boxShadow: '0 4px 12px rgba(0,0,0,0.03)', 
            height: '100%',
            transition: 'all 0.3s ease',
            '&:hover': {
              transform: 'translateY(-5px)',
              boxShadow: '0 8px 24px rgba(0,0,0,0.08)'
            }
          }}>
            <CardContent sx={{ p: 3 }}>
              <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
                <Avatar sx={{ 
                  bgcolor: '#dbeafe', 
                  p: 1,
                  boxShadow: '0 2px 8px rgba(25, 118, 210, 0.15)' 
                }}>
                  <People sx={{ color: '#2563eb' }} />
                </Avatar>
                <Typography variant="body2" sx={{ 
                  display: 'flex', 
                  alignItems: 'center',
                  color: '#16a34a', 
                  backgroundColor: 'rgba(22, 163, 74, 0.1)', 
                  p: '4px 8px', 
                  borderRadius: '16px', 
                  fontSize: '12px',
                  fontWeight: 'bold'
                }}>
                  <ArrowUpward sx={{ fontSize: 14, mr: 0.5 }} />
                  0%
                </Typography>
              </Box>
              <Typography variant="h4" fontWeight="bold" sx={{ mb: 0.5 }}>0</Typography>
              <Typography variant="body2" color="text.secondary">Tổng số khách hàng</Typography>
            </CardContent>
          </Card>
        </Grid>

        {/* Tổng doanh thu */}
        <Grid item xs={12} sm={6} md={3}>
          <Card sx={{ 
            borderRadius: '16px', 
            boxShadow: '0 4px 12px rgba(0,0,0,0.03)', 
            height: '100%',
            transition: 'all 0.3s ease',
            '&:hover': {
              transform: 'translateY(-5px)',
              boxShadow: '0 8px 24px rgba(0,0,0,0.08)'
            }
          }}>
            <CardContent sx={{ p: 3 }}>
              <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
                <Avatar sx={{ 
                  bgcolor: '#dcfce7', 
                  p: 1,
                  boxShadow: '0 2px 8px rgba(76, 175, 80, 0.15)' 
                }}>
                  <MonetizationOn sx={{ color: '#16a34a' }} />
                </Avatar>
                <Typography variant="body2" sx={{ 
                  display: 'flex', 
                  alignItems: 'center',
                  color: '#16a34a', 
                  backgroundColor: 'rgba(22, 163, 74, 0.1)', 
                  p: '4px 8px', 
                  borderRadius: '16px', 
                  fontSize: '12px',
                  fontWeight: 'bold'
                }}>
                  <ArrowUpward sx={{ fontSize: 14, mr: 0.5 }} />
                  0%
                </Typography>
              </Box>
              <Typography variant="h4" fontWeight="bold" sx={{ mb: 0.5 }}>0₫</Typography>
              <Typography variant="body2" color="text.secondary">Tổng doanh thu</Typography>
            </CardContent>
          </Card>
        </Grid>

        {/* Khách hàng tiềm năng */}
        <Grid item xs={12} sm={6} md={3}>
          <Card sx={{ 
            borderRadius: '16px', 
            boxShadow: '0 4px 12px rgba(0,0,0,0.03)', 
            height: '100%',
            transition: 'all 0.3s ease',
            '&:hover': {
              transform: 'translateY(-5px)',
              boxShadow: '0 8px 24px rgba(0,0,0,0.08)'
            }
          }}>
            <CardContent sx={{ p: 3 }}>
              <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
                <Avatar sx={{ 
                  bgcolor: '#fef9c3', 
                  p: 1,
                  boxShadow: '0 2px 8px rgba(255, 152, 0, 0.15)' 
                }}>
                  <TrendingUp sx={{ color: '#ca8a04' }} />
                </Avatar>
                <Typography variant="body2" sx={{ 
                  display: 'flex', 
                  alignItems: 'center',
                  color: '#dc2626', 
                  backgroundColor: 'rgba(220, 38, 38, 0.1)', 
                  p: '4px 8px', 
                  borderRadius: '16px', 
                  fontSize: '12px',
                  fontWeight: 'bold'
                }}>
                  <ArrowDownward sx={{ fontSize: 14, mr: 0.5 }} />
                  0%
                </Typography>
              </Box>
              <Typography variant="h4" fontWeight="bold" sx={{ mb: 0.5 }}>0</Typography>
              <Typography variant="body2" color="text.secondary">Khách hàng tiềm năng</Typography>
            </CardContent>
          </Card>
        </Grid>

        {/* Tỉ lệ chuyển đổi */}
        <Grid item xs={12} sm={6} md={3}>
          <Card sx={{ 
            borderRadius: '16px', 
            boxShadow: '0 4px 12px rgba(0,0,0,0.03)', 
            height: '100%',
            transition: 'all 0.3s ease',
            '&:hover': {
              transform: 'translateY(-5px)',
              boxShadow: '0 8px 24px rgba(0,0,0,0.08)'
            }
          }}>
            <CardContent sx={{ p: 3 }}>
              <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
                <Avatar sx={{ 
                  bgcolor: '#e0e7ff', 
                  p: 1,
                  boxShadow: '0 2px 8px rgba(63, 81, 181, 0.15)' 
                }}>
                  <Assessment sx={{ color: '#4f46e5' }} />
                </Avatar>
                <Typography variant="body2" sx={{ 
                  display: 'flex', 
                  alignItems: 'center',
                  color: '#16a34a', 
                  backgroundColor: 'rgba(22, 163, 74, 0.1)', 
                  p: '4px 8px', 
                  borderRadius: '16px', 
                  fontSize: '12px',
                  fontWeight: 'bold'
                }}>
                  <ArrowUpward sx={{ fontSize: 14, mr: 0.5 }} />
                  0%
                </Typography>
              </Box>
              <Typography variant="h4" fontWeight="bold" sx={{ mb: 0.5 }}>0%</Typography>
              <Typography variant="body2" color="text.secondary">Tỉ lệ chuyển đổi</Typography>
            </CardContent>
          </Card>
        </Grid>
      </Grid>

      <Grid container spacing={3}>
        {/* Biểu đồ doanh thu */}
        <Grid item xs={12} md={8}>
          <Card sx={{ 
            borderRadius: '16px', 
            boxShadow: '0 4px 12px rgba(0,0,0,0.03)', 
            overflow: 'hidden',
            height: '100%',
            transition: 'transform 0.3s ease',
            '&:hover': {
              boxShadow: '0 8px 24px rgba(0,0,0,0.06)'
            }
          }}>
            <CardContent>
              <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 3 }}>
                <Box>
                  <Typography variant="h6" fontWeight="bold">Biểu đồ doanh thu</Typography>
                  <Typography variant="body2" color="text.secondary">Doanh thu và chi phí trong tuần qua</Typography>
                </Box>
                <Box sx={{ display: 'flex', gap: 1 }}>
                  <Button 
                    variant="outlined" 
                    size="small" 
                    endIcon={<FilterList />}
                    onClick={handleMenuOpen}
                    sx={{ 
                      borderRadius: '8px',
                      borderColor: '#e2e8f0',
                      color: '#475569',
                      '&:hover': {
                        borderColor: '#cbd5e1',
                        backgroundColor: '#f8fafc'
                      }
                    }}
                  >
                    {timeFilter}
                  </Button>
                  <Menu
                    anchorEl={anchorEl}
                    open={Boolean(anchorEl)}
                    onClose={handleMenuClose}
                    sx={{ mt: 1 }}
                  >
                    <MenuItem onClick={() => handleTimeFilterChange('Hôm nay')}>Hôm nay</MenuItem>
                    <MenuItem onClick={() => handleTimeFilterChange('Tuần này')}>Tuần này</MenuItem>
                    <MenuItem onClick={() => handleTimeFilterChange('Tháng này')}>Tháng này</MenuItem>
                    <MenuItem onClick={() => handleTimeFilterChange('Quý này')}>Quý này</MenuItem>
                    <MenuItem onClick={() => handleTimeFilterChange('Năm nay')}>Năm nay</MenuItem>
                  </Menu>
                  <IconButton 
                    size="small" 
                    sx={{ 
                      color: '#475569',
                      bgcolor: '#f1f5f9',
                      '&:hover': {
                        bgcolor: '#e2e8f0'
                      }
                    }}
                  >
                    <Refresh fontSize="small" />
                  </IconButton>
                </Box>
              </Box>
              <Box sx={{ 
                display: 'flex', 
                justifyContent: 'center', 
                alignItems: 'center', 
                height: 320,
                flexDirection: 'column',
                gap: 2
              }}>
                <Typography color="text.secondary" variant="body1">Chưa có dữ liệu</Typography>
                <Button 
                  variant="contained" 
                  size="small"
                  sx={{ 
                    bgcolor: '#0ea5e9',
                    '&:hover': {
                      bgcolor: '#0284c7'
                    }
                  }}
                >
                  Thêm dữ liệu mới
                </Button>
              </Box>
            </CardContent>
          </Card>
        </Grid>

        {/* Khách hàng hàng đầu */}
        <Grid item xs={12} md={4}>
          <Card sx={{ 
            borderRadius: '16px', 
            boxShadow: '0 4px 12px rgba(0,0,0,0.03)',
            height: '100%',
            transition: 'transform 0.3s ease',
            '&:hover': {
              boxShadow: '0 8px 24px rgba(0,0,0,0.06)'
            }
          }}>
            <CardContent>
              <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 3 }}>
                <Typography variant="h6" fontWeight="bold">Khách hàng hàng đầu</Typography>
                <Button 
                  size="small" 
                  sx={{ 
                    color: '#0ea5e9', 
                    textTransform: 'none',
                    '&:hover': {
                      backgroundColor: 'rgba(14, 165, 233, 0.08)'
                    }
                  }}
                >
                  Xem tất cả
                </Button>
              </Box>
              <Box sx={{ 
                display: 'flex', 
                justifyContent: 'center', 
                alignItems: 'center', 
                height: 320,
                flexDirection: 'column',
                gap: 2
              }}>
                <Typography color="text.secondary" variant="body1">Chưa có dữ liệu khách hàng</Typography>
                <Button 
                  variant="outlined" 
                  size="small"
                  sx={{ 
                    borderColor: '#0ea5e9',
                    color: '#0ea5e9',
                    '&:hover': {
                      borderColor: '#0284c7',
                      backgroundColor: 'rgba(14, 165, 233, 0.04)'
                    }
                  }}
                >
                  Thêm khách hàng mới
                </Button>
              </Box>
            </CardContent>
          </Card>
        </Grid>

        {/* Biểu đồ tăng trưởng khách hàng */}
        <Grid item xs={12}>
          <Card sx={{ 
            borderRadius: '16px', 
            boxShadow: '0 4px 12px rgba(0,0,0,0.03)',
            overflow: 'hidden',
            marginTop: '16px',
            transition: 'transform 0.3s ease',
            '&:hover': {
              boxShadow: '0 8px 24px rgba(0,0,0,0.06)'
            }
          }}>
            <CardContent>
              <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 3 }}>
                <Box>
                  <Typography variant="h6" fontWeight="bold">Biểu đồ tăng trưởng khách hàng</Typography>
                  <Typography variant="body2" color="text.secondary">So sánh khách hàng mới và quay lại theo tháng</Typography>
                </Box>
                <Box sx={{ display: 'flex', gap: 1 }}>
                  <Button 
                    variant="outlined" 
                    startIcon={<CalendarToday />}
                    size="small" 
                    sx={{ 
                      borderRadius: '8px',
                      borderColor: '#e2e8f0',
                      color: '#475569',
                      '&:hover': {
                        borderColor: '#cbd5e1',
                        backgroundColor: '#f8fafc'
                      }
                    }}
                  >
                    Quý này
                  </Button>
                  <Button 
                    variant="contained" 
                    startIcon={<Download />}
                    size="small" 
                    sx={{ 
                      borderRadius: '8px', 
                      bgcolor: '#0ea5e9',
                      '&:hover': {
                        bgcolor: '#0284c7'
                      }
                    }}
                  >
                    Tải xuống
                  </Button>
                </Box>
              </Box>
              <Box sx={{ 
                display: 'flex', 
                justifyContent: 'center', 
                alignItems: 'center', 
                height: 300,
                flexDirection: 'column',
                gap: 2
              }}>
                <Typography color="text.secondary" variant="body1">Chưa có dữ liệu tăng trưởng</Typography>
                <Button 
                  variant="contained" 
                  size="small"
                  sx={{ 
                    bgcolor: '#0ea5e9',
                    '&:hover': {
                      bgcolor: '#0284c7'
                    }
                  }}
                >
                  Tạo báo cáo mới
                </Button>
              </Box>
            </CardContent>
          </Card>
        </Grid>
      </Grid>
    </Box>
  );
};

export default Dashboard;