import React, { useState, useEffect } from 'react';
import {
  Box,
  Grid,
  Card,
  CardContent,
  Typography,
  Button,
  TextField,
  MenuItem,
  FormControl,
  InputLabel,
  Select,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  IconButton,
  Chip,
  Avatar,
  InputAdornment,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  DialogContentText,
  Paper,
  Divider,
  Container,
  Tooltip,
  LinearProgress,
  CircularProgress,
  Fade
} from '@mui/material';
import {
  Edit as EditIcon,
  Delete as DeleteIcon,
  Search as SearchIcon,
  FilterList as FilterListIcon,
  PersonAdd as PersonAddIcon,
  Mail as MailIcon,
  Phone as PhoneIcon,
  Business as BusinessIcon,
  CalendarToday as CalendarIcon,
  Refresh as RefreshIcon,
  Add as AddIcon,
  ImportExport as ImportExportIcon,
  FileDownload as FileDownloadIcon,
  VisibilityOutlined as VisibilityIcon
} from '@mui/icons-material';

const QuanLyKhachHang = () => {
  // State để theo dõi danh sách khách hàng - khởi tạo mảng rỗng 
  const [customers, setCustomers] = useState([]);
  const [loading, setLoading] = useState(true);

  // State để theo dõi trạng thái form (Thêm hoặc Sửa)
  const [formMode, setFormMode] = useState('add');
  const [openForm, setOpenForm] = useState(false);
  const [selectedCustomer, setSelectedCustomer] = useState(null);
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    status: 'Active',
    createdDate: new Date().toISOString().split('T')[0],
    phone: '',
    company: ''
  });


  const [isViewing, setIsViewing] = useState(false);

  // State cho dialog xác nhận xóa
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
  const [customerToDelete, setCustomerToDelete] = useState(null);

  // State cho tìm kiếm và lọc
  const [searchQuery, setSearchQuery] = useState('');
  const [statusFilter, setStatusFilter] = useState('All');

  // State cho hiển thị loading
  const [isLoading, setIsLoading] = useState(false);
  const [tableLoading, setTableLoading] = useState(false);

  // Hàm xử lý thay đổi input form
  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData({
      ...formData,
      [name]: value
    });
  };

  // Xử lý form submission (Thêm hoặc Sửa)
  const handleSubmit = async (e) => {
    e.preventDefault();
    setIsLoading(true);

    try {
      const token = localStorage.getItem('token'); // 💬 Lấy token đã lưu

      if (formMode === 'add') {
        const response = await fetch('http://localhost:5000/api/customers/add', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'Authorization': `Bearer ${token}` // 💬 Gửi kèm Authorization
          },
          body: JSON.stringify(formData),
        });

        if (!response.ok) {
          throw new Error('Thêm khách hàng thất bại');
        }
      } else if (formMode === 'edit') {
        const response = await fetch(`http://localhost:5000/api/customers/update/${selectedCustomer._id}`, {
          method: 'PUT',
          headers: {
            'Content-Type': 'application/json',
            'Authorization': `Bearer ${token}` // 💬 Gửi kèm Authorization
          },
          body: JSON.stringify(formData),
        });

        if (!response.ok) {
          throw new Error('Cập nhật khách hàng thất bại');
        }
      }

      fetchCustomers(); // Refresh lại bảng
      setOpenForm(false);
      resetForm();
    } catch (error) {
      console.error('Lỗi khi thêm/sửa khách hàng:', error);
    } finally {
      setIsLoading(false);
    }
  };

  // Reset form fields
  const resetForm = () => {
    setFormData({
      name: '',
      email: '',
      status: 'Active',
      createdDate: new Date().toISOString().split('T')[0],
      phone: '',
      company: ''
    });
    setFormMode('add');
    setSelectedCustomer(null);
  };
  const fetchCustomers = async () => {
    try {
      const token = localStorage.getItem('token');

      const response = await fetch('http://localhost:5000/api/customers', {
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        }
      });

      if (!response.ok) {
        throw new Error('Fetch customers thất bại');
      }

      const data = await response.json();
      if (Array.isArray(data)) {
        setCustomers(data);
      } else {
        setCustomers([]);
      }
      setLoading(false);
    } catch (error) {
      console.error('Lỗi khi fetch danh sách khách hàng:', error);
      setCustomers([]);
      setLoading(false);
    }
  };


  useEffect(() => {
    fetchCustomers();
  }, []);

  // Xử lý thêm khách hàng
  const handleAddCustomer = () => {
    setFormMode('add');
    resetForm();
    setOpenForm(true);
  };

  // Xử lý sửa khách hàng
  const handleEdit = (customer) => {
    setFormMode('edit');
    setSelectedCustomer(customer);
    setFormData({
      name: customer.name,
      email: customer.email,
      status: customer.status,
      createdDate: customer.createdDate,
      phone: customer.phone,
      company: customer.company
    });
    setOpenForm(true);
  };

  // Xử lý xóa khách hàng
  const handleDeleteClick = (customer) => {
    setCustomerToDelete(customer);
    setDeleteDialogOpen(true);
  };
  const handleViewCustomer = async (customerId) => {
    try {
      const response = await fetch(`http://localhost:5000/api/customers/${customerId}`, {
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${localStorage.getItem('token')}`,
        },
      });

      if (response.ok) {
        const data = await response.json();
        setFormData({
          name: data.name,
          email: data.email,
          status: data.status,
          createdDate: data.createdDate,
          phone: data.phone,
          company: data.company,
        });
        setSelectedCustomer(data); // lưu lại khách hàng đang xem
        setFormMode('view'); // đổi mode form thành "view"
        setIsViewing(true); // bật chế độ chỉ xem
        setOpenForm(true); // mở form popup/modal
      } else {
        console.error('Không thể lấy chi tiết khách hàng');
      }
    } catch (error) {
      console.error('Lỗi khi lấy chi tiết:', error);
    }
  };

  const handleConfirmDelete = async () => {
    if (customerToDelete) {
      setTableLoading(true);

      try {
        const token = localStorage.getItem('token'); // 💬 Lấy token đã lưu

        const response = await fetch(`http://localhost:5000/api/customers/delete/${customerToDelete._id}`, {
          method: 'DELETE',
          headers: {
            'Authorization': `Bearer ${token}` // 💬 Gửi kèm Authorization
          }
        });

        if (!response.ok) {
          throw new Error('Xóa khách hàng thất bại');
        }

        fetchCustomers(); // Reload danh sách
        setDeleteDialogOpen(false);
        setCustomerToDelete(null);
      } catch (error) {
        console.error('Lỗi khi xóa khách hàng:', error);
      } finally {
        setTableLoading(false);
      }
    }
  };

  // Xử lý hủy (đóng form)
  const handleCancel = () => {
    setOpenForm(false);
    resetForm();
  };

  // Xử lý làm mới dữ liệu
  const handleRefresh = () => {
    setTableLoading(true);
    setTimeout(() => {
      fetchCustomers(); // <<< thêm dòng này: gọi lại API lấy dữ liệu
      setTableLoading(false);
    }, 800);
  };


  // Format date để hiển thị
  const formatDate = (dateString) => {
    const options = { year: 'numeric', month: 'long', day: 'numeric' };
    return new Date(dateString).toLocaleDateString('vi-VN', options);
  };

  // Lọc danh sách khách hàng
  const filteredCustomers = customers.filter(customer => {
    // Lọc theo từ khóa tìm kiếm
    const matchesSearch = customer?.name?.toLowerCase().includes(searchQuery.toLowerCase()) ||
      customer?.email?.toLowerCase().includes(searchQuery.toLowerCase()) ||
      customer?.company?.toLowerCase().includes(searchQuery.toLowerCase());

    // Lọc theo trạng thái
    const matchesStatus = statusFilter === 'All' || customer?.status === statusFilter;

    return matchesSearch && matchesStatus;
  });

  // Lấy chữ cái đầu cho avatar
  const getInitials = (name) => {
    if (!name) return '';
    return name
      .split(' ')
      .map(word => word[0])
      .join('')
      .toUpperCase()
      .substring(0, 2);
  };

  // Lấy màu nền cho avatar dựa vào trạng thái
  const getAvatarColor = (status) => {
    switch (status) {
      case 'Active':
        return '#4caf50';
      case 'Pending':
        return '#ff9800';
      case 'Inactive':
        return '#f44336';
      default:
        return '#2196f3';
    }
  };

  // Lấy màu cho chip trạng thái
  const getStatusColor = (status) => {
    switch (status) {
      case 'Active':
        return 'success';
      case 'Pending':
        return 'warning';
      case 'Inactive':
        return 'error';
      default:
        return 'default';
    }
  };

  // Dịch trạng thái sang tiếng Việt
  const translateStatus = (status) => {
    switch (status) {
      case 'Active':
        return 'Hoạt động';
      case 'Pending':
        return 'Đang chờ';
      case 'Inactive':
        return 'Không hoạt động';
      default:
        return status;
    }
  };

  return (
    <Box sx={{
      padding: { xs: '16px', sm: '24px' },
      backgroundColor: '#f8fafc',
      minHeight: '100vh',
      backgroundImage: 'linear-gradient(to bottom, #f1f5f9, #f8fafc)'
    }}>
      {/* Header */}
      <Container maxWidth="xl">
        <Paper elevation={0} sx={{
          display: 'flex',
          flexDirection: { xs: 'column', sm: 'row' },
          justifyContent: 'space-between',
          alignItems: { xs: 'flex-start', sm: 'center' },
          gap: 2,
          mb: 4,
          p: 3,
          borderRadius: 3,
          background: 'linear-gradient(135deg, #1976d2 0%, #1565c0 100%)',
          color: 'white',
          boxShadow: '0 8px 16px rgba(25, 118, 210, 0.2)'
        }}>
          <Box>
            <Typography variant="h4" fontWeight="bold" color="white" gutterBottom>
              Quản lý khách hàng
            </Typography>
            <Typography variant="subtitle1" color="rgba(255, 255, 255, 0.9)">
              Theo dõi và quản lý danh sách khách hàng của bạn
            </Typography>
          </Box>
          <Box sx={{ display: 'flex', gap: 2 }}>
            <Button
              variant="contained"
              startIcon={<RefreshIcon />}
              onClick={handleRefresh}
              sx={{
                borderRadius: '10px',
                backgroundColor: 'rgba(255, 255, 255, 0.15)',
                color: 'white',
                backdropFilter: 'blur(4px)',
                boxShadow: 'none',
                '&:hover': {
                  backgroundColor: 'rgba(255, 255, 255, 0.25)',
                  boxShadow: 'none'
                }
              }}
            >
              Làm mới
            </Button>
            <Button
              variant="contained"
              startIcon={<AddIcon />}
              onClick={handleAddCustomer}
              sx={{
                borderRadius: '10px',
                backgroundColor: 'white',
                color: '#1565c0',
                fontWeight: 'bold',
                boxShadow: '0 4px 12px rgba(0, 0, 0, 0.1)',
                '&:hover': {
                  backgroundColor: 'rgba(255, 255, 255, 0.9)'
                }
              }}
            >
              Thêm khách hàng
            </Button>
          </Box>
        </Paper>

        {/* Search and Filters */}
        <Paper elevation={0} sx={{
          mb: 3,
          p: 3,
          borderRadius: 3,
          boxShadow: '0 2px 8px rgba(0, 0, 0, 0.05)'
        }}>
          <Grid container spacing={2}>
            <Grid item xs={12} md={6}>
              <TextField
                placeholder="Tìm kiếm theo tên, email hoặc công ty..."
                variant="outlined"
                fullWidth
                size="medium"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                InputProps={{
                  startAdornment: (
                    <InputAdornment position="start">
                      <SearchIcon sx={{ color: '#607d8b' }} />
                    </InputAdornment>
                  ),
                  sx: {
                    borderRadius: 2,
                    backgroundColor: 'white'
                  }
                }}
              />
            </Grid>
            <Grid item xs={12} md={6}>
              <Box sx={{
                display: 'flex',
                gap: 2,
                justifyContent: { xs: 'flex-start', md: 'flex-end' },
                flexWrap: 'wrap'
              }}>
                <FormControl sx={{ minWidth: 200 }}>
                  <InputLabel>Trạng thái</InputLabel>
                  <Select
                    value={statusFilter}
                    onChange={(e) => setStatusFilter(e.target.value)}
                    label="Trạng thái"
                    sx={{ borderRadius: 2, backgroundColor: 'white' }}
                    startAdornment={
                      <InputAdornment position="start">
                        <FilterListIcon sx={{ color: '#607d8b', mr: 1 }} />
                      </InputAdornment>
                    }
                  >
                    <MenuItem value="All">Tất cả</MenuItem>
                    <MenuItem value="Active">Hoạt động</MenuItem>
                    <MenuItem value="Pending">Đang chờ</MenuItem>
                    <MenuItem value="Inactive">Không hoạt động</MenuItem>
                  </Select>
                </FormControl>
                <Button
                  variant="outlined"
                  startIcon={<FileDownloadIcon />}
                  sx={{
                    borderRadius: 2,
                    backgroundColor: 'white',
                    borderColor: '#e0e0e0',
                    color: '#546e7a',
                    '&:hover': {
                      borderColor: '#1976d2',
                      backgroundColor: 'white',
                    }
                  }}
                >
                  Xuất dữ liệu
                </Button>
                <Button
                  variant="outlined"
                  startIcon={<ImportExportIcon />}
                  sx={{
                    borderRadius: 2,
                    backgroundColor: 'white',
                    borderColor: '#e0e0e0',
                    color: '#546e7a',
                    '&:hover': {
                      borderColor: '#1976d2',
                      backgroundColor: 'white',
                    }
                  }}
                >
                  Nhập dữ liệu
                </Button>
              </Box>
            </Grid>
          </Grid>
        </Paper>

        {/* Customer Table */}
        <Paper elevation={0} sx={{
          borderRadius: 3,
          overflow: 'hidden',
          boxShadow: '0 2px 12px rgba(0,0,0,0.05)',
          position: 'relative'
        }}>
          {tableLoading && (
            <LinearProgress
              sx={{
                position: 'absolute',
                top: 0,
                left: 0,
                right: 0,
                height: '3px'
              }}
            />
          )}

          <TableContainer>
            <Table sx={{ minWidth: 650 }} aria-label="customer table">
              <TableHead>
                <TableRow sx={{ backgroundColor: '#f5f7fa' }}>
                  <TableCell sx={{ fontWeight: 'bold', color: '#546e7a', py: 2 }}>Khách hàng</TableCell>
                  <TableCell sx={{ fontWeight: 'bold', color: '#546e7a' }}>Email</TableCell>
                  <TableCell sx={{ fontWeight: 'bold', color: '#546e7a' }}>Trạng thái</TableCell>
                  <TableCell sx={{ fontWeight: 'bold', color: '#546e7a' }}>Ngày tạo</TableCell>
                  <TableCell sx={{ fontWeight: 'bold', color: '#546e7a' }}>Số điện thoại</TableCell>
                  <TableCell sx={{ fontWeight: 'bold', color: '#546e7a' }}>Công ty</TableCell>
                  <TableCell align="right" sx={{ fontWeight: 'bold', color: '#546e7a' }}>Thao tác</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {filteredCustomers.length > 0 ? (
                  filteredCustomers.map((customer) => (
                    <TableRow
                      key={customer._id}
                      hover
                      sx={{
                        transition: 'all 0.2s',
                        '&:hover': {
                          backgroundColor: 'rgba(25, 118, 210, 0.04)',
                        }
                      }}
                    >
                      <TableCell>
                        <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
                          <Avatar
                            sx={{
                              bgcolor: getAvatarColor(customer.status),
                              width: 40,
                              height: 40,
                              fontSize: '14px',
                              boxShadow: '0 2px 6px rgba(0,0,0,0.1)'
                            }}
                          >
                            {getInitials(customer.name)}
                          </Avatar>
                          <Typography variant="body1" fontWeight="medium">
                            {customer.name}
                          </Typography>
                        </Box>
                      </TableCell>
                      <TableCell>
                        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                          <MailIcon sx={{ fontSize: 16, color: '#607d8b' }} />
                          <Typography variant="body2">{customer.email}</Typography>
                        </Box>
                      </TableCell>
                      <TableCell>
                        <Chip
                          label={translateStatus(customer.status)}
                          color={getStatusColor(customer.status)}
                          size="small"
                          sx={{
                            borderRadius: '6px',
                            fontWeight: 500
                          }}
                        />
                      </TableCell>
                      <TableCell>
                        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                          <CalendarIcon sx={{ fontSize: 16, color: '#607d8b' }} />
                          <Typography variant="body2">{formatDate(customer.createdDate)}</Typography>
                        </Box>
                      </TableCell>
                      <TableCell>
                        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                          <PhoneIcon sx={{ fontSize: 16, color: '#607d8b' }} />
                          <Typography variant="body2">{customer.phone}</Typography>
                        </Box>
                      </TableCell>
                      <TableCell>
                        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                          <BusinessIcon sx={{ fontSize: 16, color: '#607d8b' }} />
                          <Typography variant="body2">{customer.company}</Typography>
                        </Box>
                      </TableCell>
                      <TableCell align="right">
                        <Tooltip title="Xem chi tiết">
                          <IconButton
                            size="small"
                            onClick={() => handleViewCustomer(customer._id)}
                            sx={{
                              color: '#1976d2',
                              backgroundColor: 'rgba(25, 118, 210, 0.08)',
                              mr: 1,
                              '&:hover': {
                                backgroundColor: 'rgba(25, 118, 210, 0.15)',
                              }
                            }}
                          >
                            <VisibilityIcon fontSize="small" />
                          </IconButton>
                        </Tooltip>

                        <Tooltip title="Chỉnh sửa">
                          <IconButton
                            size="small"
                            onClick={() => handleEdit(customer)}
                            sx={{
                              color: '#fb8c00',
                              backgroundColor: 'rgba(251, 140, 0, 0.08)',
                              mr: 1,
                              '&:hover': {
                                backgroundColor: 'rgba(251, 140, 0, 0.15)',
                              }
                            }}
                          >
                            <EditIcon fontSize="small" />
                          </IconButton>
                        </Tooltip>
                        <Tooltip title="Xóa">
                          <IconButton
                            size="small"
                            onClick={() => handleDeleteClick(customer)}
                            sx={{
                              color: '#f44336',
                              backgroundColor: 'rgba(244, 67, 54, 0.08)',
                              '&:hover': {
                                backgroundColor: 'rgba(244, 67, 54, 0.15)',
                              }
                            }}
                          >
                            <DeleteIcon fontSize="small" />
                          </IconButton>
                        </Tooltip>
                      </TableCell>
                    </TableRow>
                  ))
                ) : (
                  <TableRow>
                    <TableCell colSpan={7} align="center" sx={{ py: 8 }}>
                      <Box sx={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 2 }}>
                        <PersonAddIcon sx={{ fontSize: 48, color: '#607d8b', opacity: 0.5 }} />
                        <Typography variant="h6" color="text.secondary">
                          Chưa có khách hàng nào
                        </Typography>
                        <Typography variant="body2" color="text.secondary" sx={{ maxWidth: 400, textAlign: 'center', mb: 2 }}>
                          Bạn chưa có khách hàng nào trong hệ thống. Nhấn vào nút "Thêm khách hàng" để bắt đầu.
                        </Typography>
                        <Button
                          variant="contained"
                          startIcon={<AddIcon />}
                          onClick={handleAddCustomer}
                          sx={{
                            borderRadius: '10px',
                            boxShadow: '0 4px 12px rgba(25, 118, 210, 0.2)'
                          }}
                        >
                          Thêm khách hàng
                        </Button>
                      </Box>
                    </TableCell>
                  </TableRow>
                )}
              </TableBody>
            </Table>
          </TableContainer>

          {customers.length > 0 && filteredCustomers.length === 0 && (
            <Box sx={{ py: 6, textAlign: 'center' }}>
              <SearchIcon sx={{ fontSize: 48, color: '#607d8b', opacity: 0.5 }} />
              <Typography variant="h6" color="text.secondary" sx={{ mt: 2 }}>
                Không tìm thấy khách hàng nào
              </Typography>
              <Typography variant="body2" color="text.secondary" sx={{ mt: 1 }}>
                Không có khách hàng nào phù hợp với tiêu chí tìm kiếm của bạn
              </Typography>
            </Box>
          )}
        </Paper>
      </Container>

      {/* Customer Form Dialog */}
      <Dialog
        open={openForm}
        onClose={handleCancel}
        maxWidth="md"
        fullWidth
        PaperProps={{
          elevation: 24,
          sx: { borderRadius: 3 }
        }}
      >
        <DialogTitle sx={{
          borderBottom: '1px solid #e0e0e0',
          px: 3,
          py: 2,
          backgroundColor: '#f5f7fa'
        }}>
          <Typography variant="h6" fontWeight="bold">
            {formMode === 'add' ? 'Thêm khách hàng mới' : 'Chỉnh sửa thông tin khách hàng'}
          </Typography>
        </DialogTitle>
        <DialogContent sx={{ px: { xs: 2, sm: 3 }, py: 3 }}>
          <form onSubmit={handleSubmit} id="customer-form">
            <Grid container spacing={3}>
              <Grid item xs={12} sm={6}>
                <TextField
                  label="Tên khách hàng"
                  variant="outlined"
                  fullWidth
                  disabled={isViewing}
                  name="name"
                  value={formData.name}
                  onChange={handleInputChange}
                  required
                  InputProps={{
                    startAdornment: (
                      <InputAdornment position="start">
                        <PersonAddIcon sx={{ color: '#607d8b' }} />
                      </InputAdornment>
                    ),
                  }}
                  sx={{
                    '& .MuiOutlinedInput-root': {
                      borderRadius: 2
                    }
                  }}
                />
              </Grid>

              <Grid item xs={12} sm={6}>
                <TextField
                  label="Email"
                  variant="outlined"
                  fullWidth
                  disabled={isViewing}
                  name="email"
                  value={formData.email}
                  onChange={handleInputChange}
                  required
                  type="email"
                  InputProps={{
                    startAdornment: (
                      <InputAdornment position="start">
                        <MailIcon sx={{ color: '#607d8b' }} />
                      </InputAdornment>
                    ),
                  }}
                  sx={{
                    '& .MuiOutlinedInput-root': {
                      borderRadius: 2
                    }
                  }}
                />
              </Grid>

              <Grid item xs={12} sm={6}>
                <FormControl fullWidth sx={{
                  '& .MuiOutlinedInput-root': {
                    borderRadius: 2
                  }
                }}>
                  <InputLabel>Trạng thái</InputLabel>
                  <Select
                    name="status"
                    value={formData.status}
                    onChange={handleInputChange}
                    label="Trạng thái"
                  >
                    <MenuItem value="Active">Hoạt động</MenuItem>
                    <MenuItem value="Pending">Đang chờ</MenuItem>
                    <MenuItem value="Inactive">Không hoạt động</MenuItem>
                  </Select>
                </FormControl>
              </Grid>

              <Grid item xs={12} sm={6}>
                <TextField
                  label="Ngày tạo"
                  variant="outlined"
                  fullWidth
                  disabled={isViewing}
                  type="date"
                  name="createdDate"
                  value={formData.createdDate}
                  onChange={handleInputChange}
                  InputLabelProps={{
                    shrink: true,
                  }}
                  InputProps={{
                    startAdornment: (
                      <InputAdornment position="start">
                        <CalendarIcon sx={{ color: '#607d8b' }} />
                      </InputAdornment>
                    ),
                  }}
                  sx={{
                    '& .MuiOutlinedInput-root': {
                      borderRadius: 2
                    }
                  }}
                />
              </Grid>

              <Grid item xs={12} sm={6}>
                <TextField
                  label="Số điện thoại"
                  variant="outlined"
                  fullWidth
                  disabled={isViewing}
                  name="phone"
                  value={formData.phone}
                  onChange={handleInputChange}
                  InputProps={{
                    startAdornment: (
                      <InputAdornment position="start">
                        <PhoneIcon sx={{ color: '#607d8b' }} />
                      </InputAdornment>
                    ),
                  }}
                  sx={{
                    '& .MuiOutlinedInput-root': {
                      borderRadius: 2
                    }
                  }}
                />
              </Grid>

              <Grid item xs={12} sm={6}>
                <TextField
                  label="Công ty"
                  variant="outlined"
                  fullWidth
                  disabled={isViewing}
                  name="company"
                  value={formData.company}
                  onChange={handleInputChange}
                  InputProps={{
                    startAdornment: (
                      <InputAdornment position="start">
                        <BusinessIcon sx={{ color: '#607d8b' }} />
                      </InputAdornment>
                    ),
                  }}
                  sx={{
                    '& .MuiOutlinedInput-root': {
                      borderRadius: 2
                    }
                  }}
                />
              </Grid>
            </Grid>
          </form>
        </DialogContent>
        <DialogActions sx={{ px: 3, py: 2, borderTop: '1px solid #e0e0e0' }}>
          {/* Nút Đóng mới thêm */}
          {isViewing && (
            <Button
              onClick={handleCancel}
              variant="outlined"
              color="secondary"
              sx={{ borderRadius: '10px' }}
            >
              Đóng
            </Button>
          )}

          {/* Nút Hủy */}
          {!isViewing && (
            <Button
              onClick={handleCancel}
              variant="outlined"
              sx={{ borderRadius: '10px' }}
              disabled={isLoading}
            >
              Hủy
            </Button>
          )}

          {/* Nút Thêm / Lưu */}
          {!isViewing && (
            <Button
              type="submit"
              variant="contained"
              form="customer-form"
              disabled={isLoading}
              sx={{
                borderRadius: '10px',
                ml: 1,
                position: 'relative'
              }}
            >
              {isLoading ? (
                <CircularProgress size={24} color="inherit" />
              ) : (
                formMode === 'add' ? 'Thêm khách hàng' : 'Lưu thay đổi'
              )}
            </Button>
          )}
        </DialogActions>

      </Dialog>

      {/* Delete Confirmation Dialog */}
      <Dialog
        open={deleteDialogOpen}
        onClose={() => setDeleteDialogOpen(false)}
        PaperProps={{
          elevation: 24,
          sx: { borderRadius: 3 }
        }}
      >
        <DialogTitle>
          <Typography variant="h6" fontWeight="medium">Xác nhận xóa</Typography>
        </DialogTitle>
        <DialogContent>
          <DialogContentText>
            Bạn có chắc chắn muốn xóa khách hàng <b>{customerToDelete?.name}</b>? Hành động này không thể hoàn tác.
          </DialogContentText>
        </DialogContent>
        <DialogActions sx={{ px: 3, py: 2 }}>
          <Button
            onClick={() => setDeleteDialogOpen(false)}
            variant="outlined"
            sx={{ borderRadius: '10px' }}
            disabled={tableLoading}
          >
            Hủy
          </Button>
          <Button
            onClick={handleConfirmDelete}
            variant="contained"
            color="error"
            disabled={tableLoading}
            sx={{
              borderRadius: '10px',
              ml: 1,
              position: 'relative'
            }}
          >
            {tableLoading ? (
              <CircularProgress size={24} color="inherit" />
            ) : (
              'Xóa khách hàng'
            )}
          </Button>
        </DialogActions>
      </Dialog>

      {/* Snackbar thông báo */}
      <Fade in={tableLoading}>
        <Box
          sx={{
            position: 'fixed',
            bottom: 16,
            right: 16,
            zIndex: 2000,
            bgcolor: 'background.paper',
            borderRadius: 2,
            boxShadow: '0 4px 20px rgba(0,0,0,0.1)',
            display: 'flex',
            alignItems: 'center',
            px: 2,
            py: 1.5,
          }}
        >
          <CircularProgress size={20} sx={{ mr: 2, color: '#1976d2' }} />
          <Typography variant="body2">Đang xử lý...</Typography>
        </Box>
      </Fade>
    </Box>
  );
};

export default QuanLyKhachHang;